/* @autogenerated */
import { TestBed } from '@angular/core/testing';
import { of, Subject, throwError } from 'rxjs';
import { NotifyService } from '@shared/toolkit/notify/notify.service';
import { EntityImportService } from './entity-import.service';
import { ImportDefinition, ImportJob, ImportPlan, ImportTarget } from './entity-import.model';

interface Item {
  uid?: string;
  name?: string;
  enabled?: boolean;
  group?: { $ref: string };
  version?: number;
}

const KEY = 'test.items';

const plan = (rows: unknown[][], extra: Partial<ImportPlan> = {}): ImportPlan => ({
  fileName: 'items.xlsx',
  columns: [
    { field: 'name', type: 'text', label: 'Nombre', index: 0, required: true },
    { field: 'enabled', type: 'boolean', label: 'Habilitado', index: 1 },
  ],
  rows: rows.map((cells, index) => ({ row: index + 2, cells })),
  missingRequired: [],
  sensitive: false,
  canCreate: true,
  canUpdate: true,
  allowedActions: [],
  ...extra,
});

async function until(condition: () => boolean): Promise<void> {
  for (let i = 0; i < 100 && !condition(); i++) {
    await new Promise((resolve) => setTimeout(resolve));
  }
  expect(condition()).withContext('condition not reached').toBeTrue();
}

describe('EntityImportService', () => {
  let service: EntityImportService;
  let notify: jasmine.SpyObj<NotifyService>;
  let existing: Item[];
  let target: jasmine.SpyObj<ImportTarget<Item>>;
  let definition: ImportDefinition<Item>;

  beforeEach(() => {
    localStorage.removeItem('entity-import-job-' + KEY);
    localStorage.removeItem('entity-import-plan-' + KEY);
    existing = [{ uid: 'u1', name: 'ana', enabled: false, version: 3 }];
    target = jasmine.createSpyObj<ImportTarget<Item>>('target', ['acl', 'find', 'add', 'update']);
    target.find.and.callFake((values) => of(existing.filter((item) => item.name === values.name)));
    target.add.and.callFake((item) => of({ ...item, uid: 'new' }));
    target.update.and.callFake((item) => of(item));
    definition = {
      storageKey: KEY,
      scope: 'test',
      keys: ['name'],
      columns: [],
      defaults: () => ({ enabled: true }),
      target,
    };
    notify = jasmine.createSpyObj<NotifyService>('NotifyService', ['success', 'error', 'info']);
    TestBed.configureTestingModule({ providers: [{ provide: NotifyService, useValue: notify }] });
    service = TestBed.inject(EntityImportService);
  });

  it('updates the rows that exist and creates the others', async () => {
    service.start(
      definition,
      plan([
        ['ana', 'sí'],
        ['bea', null],
      ]),
    );
    const job = service.job(KEY);
    await until(() => job()?.status === 'finished');

    expect(target.update).toHaveBeenCalledWith({ uid: 'u1', name: 'ana', enabled: true, version: 3 });
    expect(target.add).toHaveBeenCalledWith({ enabled: true, name: 'bea' });
    expect(job()).toEqual(
      jasmine.objectContaining({ total: 2, processed: 2, created: 1, updated: 1, failed: 0, resumable: false }),
    );
    expect(notify.success).toHaveBeenCalled();
  });

  it('keeps the existing value when the cell is empty', async () => {
    service.start(definition, plan([['ana', '']]));
    await until(() => service.job(KEY)()?.status === 'finished');

    expect(target.update).toHaveBeenCalledWith({ uid: 'u1', name: 'ana', enabled: false, version: 3 });
  });

  it('reports the rows it cannot import without stopping', async () => {
    existing.push({ uid: 'u2', name: 'ana' });
    target.add.and.returnValue(throwError(() => ({ status: 422, error: [{ field: 'name', description: 'taken' }] })));
    service.start(definition, plan([['ana'], ['bea', 'quizá'], [null, 'sí'], ['carla']]));
    const job = service.job(KEY);
    await until(() => job()?.status === 'finished');

    expect(job()!.failed).toBe(4);
    expect(job()!.outcomes.map((o) => [o.row, o.messages?.[0].key])).toEqual([
      [2, 'common.import.error.ambiguous'],
      [3, 'common.import.error.invalid.boolean'],
      [4, 'common.import.error.missingKey'],
      [5, 'common.import.error.server'],
    ]);
    expect(job()!.outcomes[3].messages![0].params).toEqual({ status: '422', message: 'name: taken' });
    expect(notify.error).toHaveBeenCalled();
  });

  it('does not create or update without permission', async () => {
    service.start(definition, plan([['ana'], ['bea']], { canCreate: false, canUpdate: false }));
    const job = service.job(KEY);
    await until(() => job()?.status === 'finished');

    expect(job()!.outcomes.map((o) => o.messages?.[0].key)).toEqual([
      'common.import.error.notAllowed.update',
      'common.import.error.notAllowed.create',
    ]);
    expect(target.add).not.toHaveBeenCalled();
    expect(target.update).not.toHaveBeenCalled();
  });

  it('asks for the required fields only when creating', async () => {
    service.start(definition, plan([['ana'], ['bea']], { missingRequired: ['Contraseña'] }));
    const job = service.job(KEY);
    await until(() => job()?.status === 'finished');

    expect(job()!.updated).toBe(1);
    expect(job()!.outcomes[1].messages).toEqual([
      { key: 'common.import.error.missingRequired', params: { fields: 'Contraseña' } },
    ]);
  });

  it('resolves references and fails the row when there is none', async () => {
    definition.references = { group: { resolve: (text) => of(text === 'admins' ? { $ref: 'g1' } : null) } };
    const columns = [...plan([]).columns, { field: 'group', type: 'reference' as const, label: 'Grupo', index: 2 }];
    service.start(
      definition,
      plan(
        [
          ['bea', null, 'admins'],
          ['carla', null, 'nobody'],
        ],
        { columns },
      ),
    );
    const job = service.job(KEY);
    await until(() => job()?.status === 'finished');

    expect(target.add).toHaveBeenCalledWith({ enabled: true, name: 'bea', group: { $ref: 'g1' } });
    expect(job()!.outcomes[1].messages).toEqual([
      { key: 'common.import.error.reference', params: { field: 'Grupo', value: 'nobody' } },
    ]);
  });

  it('stores the state and the pending rows while it runs, and can be cancelled', async () => {
    const pending = new Subject<Item>();
    target.add.and.returnValue(pending);
    service.start(definition, plan([['bea'], ['carla']]));

    expect(service.isRunningHere(KEY)).toBeTrue();
    const stored = JSON.parse(localStorage.getItem('entity-import-job-' + KEY)!) as ImportJob;
    expect(stored.status).toBe('running');
    expect(stored.resumable).toBeTrue();
    expect(localStorage.getItem('entity-import-plan-' + KEY)).toContain('carla');

    service.cancel(KEY);
    await until(() => target.add.calls.count() === 1);
    pending.next({ name: 'bea' });
    await until(() => service.job(KEY)()?.status === 'cancelled');

    expect(service.job(KEY)()!.processed).toBe(1);
    expect(service.canResume(KEY)).toBeTrue();
  });

  it('resumes from the first pending row', async () => {
    const pending = new Subject<Item>();
    target.add.and.returnValue(pending);
    service.start(definition, plan([['bea'], ['carla']]));
    service.cancel(KEY);
    await until(() => target.add.calls.count() === 1);
    pending.next({ name: 'bea' });
    await until(() => service.job(KEY)()?.status === 'cancelled');
    target.add.calls.reset();
    target.add.and.callFake((item) => of(item));

    service.resume(definition);
    await until(() => service.job(KEY)()?.status === 'finished');

    expect(target.add).toHaveBeenCalledOnceWith({ enabled: true, name: 'carla' });
    expect(service.job(KEY)()).toEqual(jasmine.objectContaining({ processed: 2, created: 2 }));
    expect(localStorage.getItem('entity-import-plan-' + KEY)).toBeNull();
  });

  it('does not store the rows of an import with sensitive columns', () => {
    target.add.and.returnValue(new Subject<Item>());
    service.start(definition, plan([['bea']], { sensitive: true }));

    expect(localStorage.getItem('entity-import-plan-' + KEY)).toBeNull();
    expect(service.job(KEY)()!.resumable).toBeFalse();
  });

  it('marks as interrupted an import of another tab that stopped beating', () => {
    const old = new Date(Date.now() - 120_000).toISOString();
    const job: Partial<ImportJob> = {
      key: KEY,
      status: 'running',
      updatedAt: old,
      total: 3,
      processed: 1,
      outcomes: [],
    };
    localStorage.setItem('entity-import-job-' + KEY, JSON.stringify(job));

    expect(service.job(KEY)()!.status).toBe('interrupted');
    expect(JSON.parse(localStorage.getItem('entity-import-job-' + KEY)!).status).toBe('interrupted');
  });

  describe('read-only fields set through actions', () => {
    let enable: jasmine.Spy;
    let disable: jasmine.Spy;
    const statusPlan = (rows: unknown[][], extra: Partial<ImportPlan> = {}) =>
      plan(rows, {
        columns: [
          { field: 'name', type: 'text', label: 'Nombre', index: 0, required: true },
          { field: 'enabled', type: 'boolean', label: 'Habilitado', index: 1, viaAction: true },
        ],
        allowedActions: ['enable', 'disable'],
        ...extra,
      });

    beforeEach(() => {
      enable = jasmine.createSpy('enable').and.callFake((item: Item) => of({ ...item, enabled: true }));
      disable = jasmine.createSpy('disable').and.callFake((item: Item) => of({ ...item, enabled: false }));
      definition.actions = {
        enabled: [
          { name: 'enable', value: true, run: enable },
          { name: 'disable', value: false, run: disable },
        ],
      };
    });

    it('saves without the field and then runs the action that sets it', async () => {
      service.start(definition, statusPlan([['bea', 'no']]));
      const job = service.job(KEY);
      await until(() => job()?.status === 'finished');

      expect(target.add).toHaveBeenCalledWith({ enabled: true, name: 'bea' });
      expect(disable).toHaveBeenCalledWith({ enabled: true, name: 'bea', uid: 'new' });
      expect(job()).toEqual(jasmine.objectContaining({ created: 1, warned: 0 }));
      expect(job()!.outcomes[0].messages).toBeUndefined();
    });

    it('does not run the action when the saved item already has the value', async () => {
      service.start(definition, statusPlan([['ana', 'no']]));
      await until(() => service.job(KEY)()?.status === 'finished');

      expect(target.update).toHaveBeenCalledWith({ uid: 'u1', name: 'ana', enabled: false, version: 3 });
      expect(enable).not.toHaveBeenCalled();
      expect(disable).not.toHaveBeenCalled();
    });

    it('warns when the action is not allowed, keeping the row saved', async () => {
      service.start(definition, statusPlan([['ana', 'sí']], { allowedActions: ['disable'] }));
      const job = service.job(KEY);
      await until(() => job()?.status === 'finished');

      expect(enable).not.toHaveBeenCalled();
      expect(job()).toEqual(jasmine.objectContaining({ updated: 1, failed: 0, warned: 1 }));
      expect(job()!.outcomes[0].messages).toEqual([
        { key: 'common.import.warn.notAllowed', params: { field: 'Habilitado', value: 'sí', action: 'enable' } },
      ]);
      expect(notify.info).toHaveBeenCalled();
    });

    it('warns when no action leads to the value', async () => {
      definition.actions = { enabled: [{ name: 'enable', value: true, run: enable }] };
      service.start(
        definition,
        statusPlan([
          ['ana', 'no'],
          ['bea', 'no'],
        ]),
      );
      const job = service.job(KEY);
      await until(() => job()?.status === 'finished');

      // "ana" ya está deshabilitada; "bea" se crea habilitada y no hay acción para deshabilitarla
      expect(job()!.outcomes.map((o) => o.messages?.[0]?.key)).toEqual([undefined, 'common.import.warn.noAction']);
    });

    it('warns with the server message when the action fails', async () => {
      disable.and.returnValue(throwError(() => ({ status: 409, error: { message: 'last admin' } })));
      service.start(definition, statusPlan([['bea', 'no']]));
      const job = service.job(KEY);
      await until(() => job()?.status === 'finished');

      expect(job()).toEqual(jasmine.objectContaining({ created: 1, warned: 1 }));
      expect(job()!.outcomes[0].messages).toEqual([
        {
          key: 'common.import.warn.actionFailed',
          params: { field: 'Habilitado', value: 'no', action: 'disable', message: 'last admin' },
        },
      ]);
    });
  });

  it('forgets a finished import', async () => {
    service.start(definition, plan([['bea']]));
    await until(() => service.job(KEY)()?.status === 'finished');

    service.clear(KEY);

    expect(service.job(KEY)()).toBeNull();
    expect(localStorage.getItem('entity-import-job-' + KEY)).toBeNull();
  });
});
